const euro=new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'});const dateFmt=new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'});
const defaults={goal:{name:'Notreserve',target:1000,date:'2026-12-31'},pin:'258014',transactions:[{id:1,type:'deposit',amount:50,note:'Startbetrag',date:'2026-08-28T10:00:00'},{id:2,type:'deposit',amount:20,note:'Wochenbudget',date:'2026-09-02T18:30:00'},{id:3,type:'deposit',amount:10,note:'Bargeld gespart',date:'2026-09-05T12:15:00'},{id:4,type:'deposit',amount:5,note:'Kleingeld',date:'2026-09-07T20:10:00'},{id:5,type:'deposit',amount:20,note:'Einzahlung',date:'2026-09-08T18:20:00'}]};
let state=load(),modalMode='deposit';function load(){try{return JSON.parse(localStorage.getItem('sparbox-state'))||structuredClone(defaults)}catch{return structuredClone(defaults)}}function save(){localStorage.setItem('sparbox-state',JSON.stringify(state))}function balance(){return state.transactions.reduce((s,t)=>s+(t.type==='deposit'?t.amount:-t.amount),0)}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function showToast(msg){const e=document.querySelector('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>e.classList.remove('show'),2600)}
function render(){const b=balance(),target=Number(state.goal.target)||1,p=Math.min(100,Math.max(0,b/target*100)),remaining=Math.max(0,target-b);document.querySelector('#balanceValue').textContent=euro.format(b);document.querySelector('#goalPercent').textContent=Math.round(p)+'%';document.querySelector('#goalRing').style.setProperty('--p',p);document.querySelector('#goalName').textContent=state.goal.name;document.querySelector('#goalCurrent').textContent=euro.format(b);document.querySelector('#goalTarget').textContent=euro.format(target);document.querySelector('#goalRemaining').textContent=remaining?`Noch ${euro.format(remaining)}`:'Ziel erreicht 🎉';document.querySelector('#forecastRemaining').textContent=euro.format(remaining);const end=new Date(state.goal.date+'T12:00:00'),now=new Date(),months=Math.max(1,(end.getFullYear()-now.getFullYear())*12+end.getMonth()-now.getMonth());document.querySelector('#monthlyNeeded').textContent=euro.format(remaining/months);document.querySelector('#targetDateTitle').textContent=`Ziel bis ${dateFmt.format(end)}`;renderRecent();renderTable();renderGoal();renderStatement()}
function sorted(){return [...state.transactions].sort((a,b)=>new Date(b.date)-new Date(a.date))}function txRow(t){return `<div class="transaction-row"><div class="transaction-icon ${t.type==='withdraw'?'withdraw':''}">${t.type==='deposit'?'↓':'↑'}</div><div class="transaction-copy"><strong>${esc(t.note|| (t.type==='deposit'?'Einzahlung':'Auszahlung'))}</strong><small>${dateFmt.format(new Date(t.date))}</small></div><span class="amount ${t.type==='withdraw'?'withdraw':''}">${t.type==='deposit'?'+':'−'}${euro.format(t.amount)}</span></div>`}function renderRecent(){const a=sorted().slice(0,5);document.querySelector('#recentTransactions').innerHTML=a.length?a.map(txRow).join(''):'<div class="empty">Noch keine Buchungen.</div>'}
function balancesById(){let s=0,m={};[...state.transactions].sort((a,b)=>new Date(a.date)-new Date(b.date)).forEach(t=>{s+=t.type==='deposit'?t.amount:-t.amount;m[t.id]=s});return m}function renderTable(){const q=(document.querySelector('#searchInput')?.value||'').toLowerCase(),f=document.querySelector('#typeFilter')?.value||'all',bm=balancesById();const a=sorted().filter(t=>(f==='all'||t.type===f)&&(t.note||'').toLowerCase().includes(q));document.querySelector('#transactionTable').innerHTML=a.length?a.map(t=>`<tr><td>${dateFmt.format(new Date(t.date))}</td><td>${esc(t.note||'–')}</td><td><span class="type-pill ${t.type==='withdraw'?'withdraw':''}">${t.type==='deposit'?'Einzahlung':'Auszahlung'}</span></td><td class="right amount ${t.type==='withdraw'?'withdraw':''}">${t.type==='deposit'?'+':'−'}${euro.format(t.amount)}</td><td class="right">${euro.format(bm[t.id])}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">Keine passenden Buchungen.</td></tr>'}
function renderGoal(){document.querySelector('#goalNameInput').value=state.goal.name;document.querySelector('#goalAmountInput').value=state.goal.target;document.querySelector('#goalDateInput').value=state.goal.date;const b=balance();document.querySelector('#milestones').innerHTML=[25,50,75,100].map(x=>{const value=state.goal.target*x/100,done=b>=value;return `<div class="milestone ${done?'done':''}"><div class="milestone-badge">${done?'✓':x+'%'}</div><div><strong>${x}% erreicht</strong><small>${euro.format(value)}</small></div><span>${done?'Geschafft':'Offen'}</span></div>`}).join('')}
function renderStatement(){const b=balance(),dep=state.transactions.filter(t=>t.type==='deposit').reduce((s,t)=>s+t.amount,0),wd=state.transactions.filter(t=>t.type==='withdraw').reduce((s,t)=>s+t.amount,0),bm=balancesById();document.querySelector('#statementPreview').innerHTML=`<div class="statement-brand"><div><span class="eyebrow">Privater Sparauszug</span><h2>SparBox</h2></div><div>Erstellt am ${dateFmt.format(new Date())}</div></div><h3>${esc(state.goal.name)}</h3><div class="statement-summary"><div><small>Einzahlungen</small><strong>${euro.format(dep)}</strong></div><div><small>Auszahlungen</small><strong>${euro.format(wd)}</strong></div><div><small>Endbestand</small><strong>${euro.format(b)}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Datum</th><th>Beschreibung</th><th class="right">Betrag</th><th class="right">Stand</th></tr></thead><tbody>${sorted().map(t=>`<tr><td>${dateFmt.format(new Date(t.date))}</td><td>${esc(t.note||'–')}</td><td class="right">${t.type==='deposit'?'+':'−'}${euro.format(t.amount)}</td><td class="right">${euro.format(bm[t.id])}</td></tr>`).join('')}</tbody></table></div>`}
function switchView(name){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));document.querySelectorAll('.nav-item').forEach(v=>v.classList.toggle('active',v.dataset.view===name));document.querySelector('#viewTitle').textContent=({overview:'Übersicht',transactions:'Buchungen',goal:'Sparziel',statement:'Kontoauszug',settings:'Einstellungen'})[name];document.querySelector('.sidebar').classList.remove('open')}
function openModal(mode){modalMode=mode;const tx=mode!=='unlock';document.querySelector('#transactionForm').hidden=!tx;document.querySelector('#unlockForm').hidden=tx;document.querySelector('#modalEyebrow').textContent=mode==='unlock'?'Sicherheit':'Neue Buchung';document.querySelector('#modalTitle').textContent=mode==='deposit'?'Einzahlung hinzufügen':mode==='withdraw'?'Auszahlung erfassen':'SparBox öffnen';document.querySelector('#modalHint').textContent=mode==='deposit'?'Trage den Betrag ein, den du in die Box gelegt hast.':mode==='withdraw'?'Der Betrag wird vom aktuellen Sparstand abgezogen.':'Gib deinen sechsstelligen Öffnungs-PIN ein.';document.querySelector('#transactionSubmit').textContent=mode==='deposit'?'Einzahlung speichern':'Auszahlung speichern';document.querySelector('#modalBackdrop').hidden=false;setTimeout(()=>document.querySelector(tx?'#amountInput':'#unlockPin').focus(),50)}function closeModal(){document.querySelector('#modalBackdrop').hidden=true;document.querySelector('#transactionForm').reset();document.querySelector('#unlockForm').reset()}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));document.querySelectorAll('[data-view-jump]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.viewJump)));document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>openModal(b.dataset.open)));document.querySelector('#menuBtn').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));document.querySelector('#modalClose').addEventListener('click',closeModal);document.querySelector('#modalBackdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.querySelectorAll('[data-amount]').forEach(b=>b.addEventListener('click',()=>document.querySelector('#amountInput').value=b.dataset.amount));
document.querySelector('#transactionForm').addEventListener('submit',e=>{e.preventDefault();const amount=Number(document.querySelector('#amountInput').value);if(!amount)return;if(modalMode==='withdraw'&&amount>balance()){showToast('Auszahlung ist höher als der Sparstand.');return}state.transactions.push({id:Date.now(),type:modalMode,amount,note:document.querySelector('#noteInput').value.trim()||(modalMode==='deposit'?'Einzahlung':'Auszahlung'),date:new Date().toISOString()});save();render();closeModal();showToast(`${modalMode==='deposit'?'Einzahlung':'Auszahlung'} gespeichert.`)});
document.querySelector('#unlockForm').addEventListener('submit',e=>{e.preventDefault();if(document.querySelector('#unlockPin').value===state.pin){closeModal();showToast('PIN korrekt – Öffnung wurde simuliert.')}else showToast('PIN ist nicht korrekt.')});document.querySelector('#goalForm').addEventListener('submit',e=>{e.preventDefault();state.goal={name:document.querySelector('#goalNameInput').value.trim(),target:Number(document.querySelector('#goalAmountInput').value),date:document.querySelector('#goalDateInput').value};save();render();showToast('Sparziel gespeichert.')});document.querySelector('#pinForm').addEventListener('submit',e=>{e.preventDefault();const a=document.querySelector('#pinInput').value,b=document.querySelector('#pinConfirm').value;if(!/^\d{6}$/.test(a)){showToast('Der PIN muss aus sechs Zahlen bestehen.');return}if(a!==b){showToast('Die PIN-Eingaben stimmen nicht überein.');return}state.pin=a;save();e.target.reset();showToast('PIN wurde geändert.')});document.querySelector('#searchInput').addEventListener('input',renderTable);document.querySelector('#typeFilter').addEventListener('change',renderTable);document.querySelector('#resetData').addEventListener('click',()=>{if(confirm('Alle lokalen Testdaten wirklich zurücksetzen?')){state=structuredClone(defaults);save();render();showToast('Testdaten wurden zurückgesetzt.')}});
function pdfEscape(s){return String(s).replace(/[^\x20-\x7E]/g,c=>({'ä':'ae','ö':'oe','ü':'ue','Ä':'Ae','Ö':'Oe','Ü':'Ue','ß':'ss','€':'EUR'}[c]||'')).replace(/([\\()])/g,'\\$1')}function makePdf(){const lines=[`SparBox - Kontoauszug`,`Sparziel: ${state.goal.name}`,`Erstellt: ${dateFmt.format(new Date())}`,`Aktueller Stand: ${euro.format(balance())}`,'','Datum       Beschreibung                         Betrag'];sorted().slice(0,35).forEach(t=>lines.push(`${dateFmt.format(new Date(t.date))}   ${(t.note||'Buchung').slice(0,32).padEnd(34)} ${t.type==='deposit'?'+':'-'}${t.amount.toFixed(2)} EUR`));let y=790,content='BT /F1 12 Tf 50 810 Td ';lines.forEach((l,i)=>{content+=`${i?'0 -19 Td ':''}(${pdfEscape(l)}) Tj `});content+='ET';const objs=[`<< /Type /Catalog /Pages 2 0 R >>`,`<< /Type /Pages /Kids [3 0 R] /Count 1 >>`,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>`,`<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>`,`<< /Length ${content.length} >>\nstream\n${content}\nendstream`];let pdf='%PDF-1.4\n',offs=[0];objs.forEach((o,i)=>{offs.push(pdf.length);pdf+=`${i+1} 0 obj\n${o}\nendobj\n`});const x=pdf.length;pdf+=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`;offs.slice(1).forEach(o=>pdf+=String(o).padStart(10,'0')+' 00000 n \n');pdf+=`trailer << /Size ${objs.length+1} /Root 1 0 R >>\nstartxref\n${x}\n%%EOF`;const url=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=`SparBox-Kontoauszug-${new Date().toISOString().slice(0,10)}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}document.querySelector('#downloadPdf').addEventListener('click',makePdf);
function tick(){const n=new Date();document.querySelector('#clockTime').textContent=n.toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'});document.querySelector('#clockDate').textContent=dateFmt.format(n);document.querySelector('#todayLabel').textContent=n.toLocaleDateString('de-DE',{weekday:'long'})}tick();setInterval(tick,1000);render();
